pll mysub(pll &a, pll &b)
{
	ll cz = lcm(a.second, b.second);
	ll ac = cz / a.second;
	ll bc = cz / b.second;
	ll rt = a.first * ac - b.first * bc;
	ll gcdr = gcd(abs(rt), cz);
	return pll(rt / gcdr, cz / gcdr);
}

pll myabs(pll a)
{
	if (a.first < 0)
		return pll(-a.first, a.second);
	return a;
}

int compare(pll &a, pll &b)
{
	ll cz = lcm(a.second, b.second);
	ll ac = cz / a.second;
	ll bc = cz / b.second;
	ll na = a.first * ac;
	ll nb = b.first * bc;
	if (na == nb)
		return 0;
	if (na < nb)
		return -1;
	return 1;

}

